/bin/bash -lc "cd /work && python - <<'PY'
from sim import Sim
import numpy as np

def pitch(sim):
    xmat=sim.data.xmat[sim.torso_body_id].reshape(3,3)
    up=xmat[:,2]
    return float(np.arctan2(up[0], up[2]))

names=Sim().actuator_names();
idx={n:i for i,n in enumerate(names)}

for ankle_tau in [10,-10]:
    sim=Sim(); sim.reset();
    sim.data.ctrl[:] = 0
    sim.step(50)
    sim.data.ctrl[idx['left_ankle']] = ankle_tau
    sim.data.ctrl[idx['right_ankle']] = ankle_tau
    sim.step(500)
    print('ankle',ankle_tau,'pelvis',sim.pelvis_position(),'pitch',pitch(sim),'torso_up',sim.torso_up())
PY"

